draw ((0,0)--(0,1));
draw ((0,0)--(1,0));
draw ((0,1)--(.5,1));
draw ((.5,1)--(.5,0));
draw ((0,.5)--(1,.5));
draw ((1,.5)--(1,0));
draw ((1,.5)--(1,0));
[/asy]
